create or replace function public.public_settings()
returns json language sql stable security definer set search_path = '' as $$
  select json_build_object('acceptSignups', accept_signups, 'askCompany', ask_company,
    'requiredFields', required_fields || '{"name": true, "email": true}'::jsonb)
  from public.app_settings where id = 1;
$$;

create or replace function public.register_for_event(p_event_id uuid, p_answers jsonb)
returns json language plpgsql security definer set search_path = '' as $$
declare ev public.events; req jsonb; k text; r public.event_registrations;
begin
  select * into ev from public.events where id = p_event_id and published;
  if not found then raise exception 'That event no longer exists.' using errcode = 'P0001'; end if;
  select required_fields || '{"name": true, "email": true}'::jsonb into req from public.app_settings where id = 1;
  for k in select key from jsonb_each(req) where value = 'true'::jsonb loop
    if btrim(coalesce(p_answers ->> k, '')) = '' then
      raise exception 'Please fill in the required fields to register.' using errcode = 'P0001';
    end if;
  end loop;
  if (p_answers ->> 'email') !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' then
    raise exception 'Enter a valid email, like you@company.com.' using errcode = 'P0001';
  end if;
  begin
    insert into public.event_registrations (event_id, name, email, company, role, company_size, heard_from)
    values (p_event_id, left(btrim(p_answers ->> 'name'), 200), btrim(p_answers ->> 'email'),
      nullif(left(btrim(coalesce(p_answers ->> 'company', '')), 200), ''), nullif(p_answers ->> 'role', ''),
      nullif(p_answers ->> 'size', ''), nullif(p_answers ->> 'heard', ''))
    returning * into r;
  exception when unique_violation then
    raise exception 'This email is already registered for this event.' using errcode = 'P0001';
  end;
  return json_build_object('id', r.id, 'eventId', r.event_id, 'cancelToken', r.cancel_token);
end;
$$;

create or replace function public.cancel_registration(p_id bigint, p_token uuid)
returns json language sql security definer set search_path = '' as $$
  with d as (delete from public.event_registrations where id = p_id and cancel_token = p_token returning id)
  select json_build_object('ok', exists (select 1 from d));
$$;

create or replace function public.published_events()
returns setof json language sql stable security definer set search_path = '' as $$
  select json_build_object('id', e.id, 'type', e.type, 'title', e.title, 'description', e.description,
    'length', e.length_label, 'whenLabel', e.when_label, 'startsAt', e.starts_at, 'location', e.location,
    'capacity', e.capacity)
  from public.events e where e.published order by e.sort_order, e.starts_at nulls last, e.created_at desc;
$$;

revoke execute on function public.public_settings(), public.register_for_event(uuid, jsonb),
  public.cancel_registration(bigint, uuid), public.published_events() from public;
grant execute on function public.public_settings(), public.register_for_event(uuid, jsonb),
  public.cancel_registration(bigint, uuid), public.published_events() to anon, authenticated;

-- ═══ 20261030154532_registration_confirmation_email.sql ══════════════════════════════
-- Confirmation email ("You're in.") on every new event registration.
create extension if not exists pg_net with schema extensions;

alter table public.event_registrations
  add column if not exists confirmation_sent_at timestamptz,
  add column if not exists confirmation_error text;
-- Per-event "Get ready" checklist for the email (null = default list in the function).
alter table public.events add column if not exists prep_items text[];

-- Shared secret between the trigger and the Edge Function, kept in Vault.
select vault.create_secret(encode(extensions.gen_random_bytes(32), 'hex'), 'registration_email_webhook', 'Auth for the registration-email Edge Function')
where not exists (select 1 from vault.secrets where name = 'registration_email_webhook');

create or replace function public.check_registration_webhook(p_secret text)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from vault.decrypted_secrets where name = 'registration_email_webhook' and decrypted_secret = p_secret);
$$;
revoke execute on function public.check_registration_webhook(text) from public, anon, authenticated;
grant execute on function public.check_registration_webhook(text) to service_role;

create or replace function private.send_registration_email()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  perform net.http_post(
    url := 'https://gwdrtfcqqnvhwolbjkab.supabase.co/functions/v1/registration-email',
    body := jsonb_build_object('registration_id', new.id,
      'secret', (select decrypted_secret from vault.decrypted_secrets where name = 'registration_email_webhook')),
    headers := jsonb_build_object('Content-Type', 'application/json'),
    timeout_milliseconds := 10000
  );
  return new;
end;
$$;
revoke execute on function private.send_registration_email() from public, anon, authenticated;

create trigger event_registrations_confirmation_email after insert on public.event_registrations
  for each row execute function private.send_registration_email();

-- ═══ 20261031070000_site_visitors.sql ════════════════════════════════════════════════
-- Unique website visitors for Admin › Visitors.
-- One row per person. A visit is matched to an existing person by, in order:
-- signed-in email, then browser id (kept in the browser), then IP address.
-- Refreshing or moving between pages never adds a person, and only counts as a
-- new visit after 30 minutes without activity.
create table public.site_visitors (
  id          bigint generated always as identity primary key,
  email       text,
  user_id     uuid references auth.users (id) on delete set null,
  browser_id  uuid,
  ip          text,
  user_agent  text,
  referrer    text,
  first_path  text,
  last_path   text,
  visits      integer not null default 1,
  first_seen  timestamptz not null default now(),
  last_seen   timestamptz not null default now()
);
create index site_visitors_email_idx on public.site_visitors (lower(email));
create index site_visitors_browser_idx on public.site_visitors (browser_id);
create index site_visitors_ip_idx on public.site_visitors (ip);
create index site_visitors_last_seen_idx on public.site_visitors (last_seen desc);

alter table public.site_visitors enable row level security;
create policy "Admins read visitors" on public.site_visitors for select to authenticated using (private.is_admin());
create policy "Admins delete visitors" on public.site_visitors for delete to authenticated using (private.is_admin());

create or replace function public.track_visit(p_browser_id uuid, p_path text default null, p_referrer text default null)
returns void language plpgsql security definer set search_path = '' as $$
declare
  h json := coalesce(nullif(current_setting('request.headers', true), ''), '{}')::json;
  v_ip text := nullif(trim(split_part(coalesce(h->>'cf-connecting-ip', h->>'x-real-ip', h->>'x-forwarded-for', ''), ',', 1)), '');
  v_ua text := left(h->>'user-agent', 400);
  v_uid uuid := auth.uid();
  v_email text := lower(nullif(auth.jwt()->>'email', ''));
  v_path text := left(p_path, 300);
  v_id bigint;
begin
  if v_ua ~* '(bot|crawl|spider|slurp|preview|headless|lighthouse|monitor)' then return; end if;

  if v_email is not null then
    select id into v_id from public.site_visitors where lower(email) = v_email order by first_seen limit 1;
  end if;
  if v_id is null and p_browser_id is not null then
    select id into v_id from public.site_visitors
     where browser_id = p_browser_id and (email is null or v_email is null or lower(email) = v_email)
     order by first_seen limit 1;
  end if;
  if v_id is null and v_ip is not null then
    select id into v_id from public.site_visitors
     where ip = v_ip and (email is null or v_email is null or lower(email) = v_email)
     order by first_seen limit 1;
  end if;

  if v_id is null then
    insert into public.site_visitors (email, user_id, browser_id, ip, user_agent, referrer, first_path, last_path)
    values (v_email, v_uid, p_browser_id, v_ip, v_ua, left(nullif(p_referrer, ''), 300), v_path, v_path);
  else
    update public.site_visitors set
      visits     = visits + case when last_seen < now() - interval '30 minutes' then 1 else 0 end,
      last_seen  = now(),
      last_path  = coalesce(v_path, last_path),
      email      = coalesce(email, v_email),
      user_id    = coalesce(user_id, v_uid),
      browser_id = coalesce(browser_id, p_browser_id),
      ip         = coalesce(v_ip, ip),
      user_agent = coalesce(v_ua, user_agent)
    where id = v_id;
  end if;
end;
$$;
revoke execute on function public.track_visit(uuid, text, text) from public;
grant execute on function public.track_visit(uuid, text, text) to anon, authenticated;

-- ═══ 20261031080000_site_visitors_location.sql ═══════════════════════════════════════
-- Location and campaign source for Admin › Visitors.
-- Country comes from Cloudflare's cf-ipcountry header on the request to Supabase (the
-- visitor cannot change it). City and region come from Vercel's IP lookup, passed in
-- by the website. utm_source is kept from the first landing URL.
alter table public.site_visitors
  add column if not exists country text,
  add column if not exists region  text,
  add column if not exists city    text,
  add column if not exists source  text;

drop function if exists public.track_visit(uuid, text, text);

create or replace function public.track_visit(
  p_browser_id uuid, p_path text default null, p_referrer text default null,
  p_country text default null, p_region text default null, p_city text default null, p_source text default null)
returns void language plpgsql security definer set search_path = '' as $$
declare
  h json := coalesce(nullif(current_setting('request.headers', true), ''), '{}')::json;
  v_ip text := nullif(trim(split_part(coalesce(h->>'cf-connecting-ip', h->>'x-real-ip', h->>'x-forwarded-for', ''), ',', 1)), '');
  v_ua text := left(h->>'user-agent', 400);
  v_country text := upper(coalesce(nullif(h->>'cf-ipcountry', ''), nullif(left(p_country, 2), '')));
  v_region text := nullif(left(p_region, 80), '');
  v_city text := nullif(left(p_city, 80), '');
  v_uid uuid := auth.uid();
  v_email text := lower(nullif(auth.jwt()->>'email', ''));
  v_path text := left(p_path, 300);
  v_id bigint;
begin
  if v_ua ~* '(bot|crawl|spider|slurp|preview|headless|lighthouse|monitor)' then return; end if;
  if v_country in ('XX', 'T1') then v_country := null; end if;

  if v_email is not null then
    select id into v_id from public.site_visitors where lower(email) = v_email order by first_seen limit 1;
  end if;
  if v_id is null and p_browser_id is not null then
    select id into v_id from public.site_visitors
     where browser_id = p_browser_id and (email is null or v_email is null or lower(email) = v_email)
     order by first_seen limit 1;
  end if;
  if v_id is null and v_ip is not null then
    select id into v_id from public.site_visitors
     where ip = v_ip and (email is null or v_email is null or lower(email) = v_email)
     order by first_seen limit 1;
  end if;

  if v_id is null then
    insert into public.site_visitors (email, user_id, browser_id, ip, user_agent, referrer, source, first_path, last_path, country, region, city)
    values (v_email, v_uid, p_browser_id, v_ip, v_ua, left(nullif(p_referrer, ''), 300), left(nullif(p_source, ''), 80),
            v_path, v_path, v_country, v_region, v_city);
  else
    update public.site_visitors set
      visits     = visits + case when last_seen < now() - interval '30 minutes' then 1 else 0 end,
      last_seen  = now(),
      last_path  = coalesce(v_path, last_path),
      email      = coalesce(email, v_email),
      user_id    = coalesce(user_id, v_uid),
      browser_id = coalesce(browser_id, p_browser_id),
      ip         = coalesce(v_ip, ip),
      user_agent = coalesce(v_ua, user_agent),
      country    = coalesce(v_country, country),
      region     = case when v_city is not null or v_region is not null then v_region else region end,
      city       = coalesce(v_city, city)
    where id = v_id;
  end if;
end;
$$;
revoke execute on function public.track_visit(uuid, text, text, text, text, text, text) from public;
grant execute on function public.track_visit(uuid, text, text, text, text, text, text) to anon, authenticated;

-- ═══ 20261031090000_site_visitors_exclude_team.sql ═══════════════════════════════════
-- Team members (owners/admins) are remembered but hidden from Admin › Visitors, including
-- later visits from the same browser or IP while signed out.
alter table public.site_visitors add column if not exists is_team boolean not null default false;

update public.site_visitors v set is_team = true
  from public.profiles p where p.role in ('owner', 'admin') and lower(p.email) = lower(v.email);

create or replace function private.mark_team_visitor() returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if not new.is_team and new.user_id is not null and exists (
       select 1 from public.profiles p where p.id = new.user_id and p.role in ('owner', 'admin')) then
    new.is_team := true;
  end if;
  return new;
end;
$$;
revoke execute on function private.mark_team_visitor() from public, anon, authenticated;
create trigger site_visitors_mark_team before insert or update of user_id, email on public.site_visitors
  for each row execute function private.mark_team_visitor();

-- ═══ 20261031100000_site_visitors_no_ip_merge.sql ════════════════════════════════════
-- Match a person by signed-in email or browser id only. IP is still recorded and shown,
-- but no longer merges people: different computers on the same Wi-Fi are separate visitors.
create or replace function public.track_visit(
  p_browser_id uuid, p_path text default null, p_referrer text default null,
  p_country text default null, p_region text default null, p_city text default null, p_source text default null)
returns void language plpgsql security definer set search_path = '' as $$
declare
  h json := coalesce(nullif(current_setting('request.headers', true), ''), '{}')::json;
  v_ip text := nullif(trim(split_part(coalesce(h->>'cf-connecting-ip', h->>'x-real-ip', h->>'x-forwarded-for', ''), ',', 1)), '');
  v_ua text := left(h->>'user-agent', 400);
  v_country text := upper(coalesce(nullif(h->>'cf-ipcountry', ''), nullif(left(p_country, 2), '')));
  v_region text := nullif(left(p_region, 80), '');
  v_city text := nullif(left(p_city, 80), '');
  v_uid uuid := auth.uid();
  v_email text := lower(nullif(auth.jwt()->>'email', ''));
  v_path text := left(p_path, 300);
  v_id bigint;
begin
  if v_ua ~* '(bot|crawl|spider|slurp|preview|headless|lighthouse|monitor)' then return; end if;
  if v_country in ('XX', 'T1') then v_country := null; end if;

  if v_email is not null then
    select id into v_id from public.site_visitors where lower(email) = v_email order by first_seen limit 1;
  end if;
  if v_id is null and p_browser_id is not null then
    select id into v_id from public.site_visitors
     where browser_id = p_browser_id and (email is null or v_email is null or lower(email) = v_email)
     order by first_seen limit 1;
  end if;

  if v_id is null then
    insert into public.site_visitors (email, user_id, browser_id, ip, user_agent, referrer, source, first_path, last_path, country, region, city)
    values (v_email, v_uid, p_browser_id, v_ip, v_ua, left(nullif(p_referrer, ''), 300), left(nullif(p_source, ''), 80),
            v_path, v_path, v_country, v_region, v_city);
  else
    update public.site_visitors set
      visits     = visits + case when last_seen < now() - interval '30 minutes' then 1 else 0 end,
      last_seen  = now(),
      last_path  = coalesce(v_path, last_path),
      email      = coalesce(email, v_email),
      user_id    = coalesce(user_id, v_uid),
      browser_id = coalesce(browser_id, p_browser_id),
      ip         = coalesce(v_ip, ip),
      user_agent = coalesce(v_ua, user_agent),
      country    = coalesce(v_country, country),
      region     = case when v_city is not null or v_region is not null then v_region else region end,
      city       = coalesce(v_city, city)
    where id = v_id;
  end if;
end;
$$;

-- ═══ 20261031110000_site_visitors_names.sql ══════════════════════════════════════════
-- Names for Admin › Visitors. A visitor gets a name and email when they join the
-- waitlist, register for an event, or sign in. Everyone else stays anonymous.
alter table public.site_visitors add column if not exists name text;

-- Called by the website right after a waitlist sign-up or event registration.
-- Only accepts an email that really is on the waitlist or registered for an event.
create or replace function public.identify_visitor(p_browser_id uuid, p_email text)
returns void language plpgsql security definer set search_path = '' as $$
declare
  v_email text := lower(trim(p_email));
  v_name text;
begin
  if p_browser_id is null or v_email is null or v_email = '' then return; end if;
  select name into v_name from (
    select name, created_at from public.event_registrations where lower(email) = v_email
    union all
    select name, created_at from public.waitlist_entries where lower(email) = v_email
  ) x order by created_at desc limit 1;
  if v_name is null then return; end if;

  update public.site_visitors
     set name = v_name, email = coalesce(email, v_email), last_seen = now()
   where browser_id = p_browser_id and (email is null or lower(email) = v_email);
end;
$$;
revoke execute on function public.identify_visitor(uuid, text) from public;
grant execute on function public.identify_visitor(uuid, text) to anon, authenticated;

-- Signed-in visitors: take the name from their profile.
create or replace function private.name_visitor_from_profile() returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if new.name is null and new.user_id is not null then
    select nullif(full_name, '') into new.name from public.profiles where id = new.user_id;
  end if;
  return new;
end;
$$;
revoke execute on function private.name_visitor_from_profile() from public, anon, authenticated;
create trigger site_visitors_name_from_profile before insert or update on public.site_visitors
  for each row execute function private.name_visitor_from_profile();

-- Fill names for visitors already matched by email.
update public.site_visitors v set name = x.name
  from (
    select distinct on (lower(email)) lower(email) as em, name from (
      select email, name, created_at from public.event_registrations
      union all select email, name, created_at from public.waitlist_entries
      union all select email, full_name, created_at from public.profiles where coalesce(full_name, '') <> ''
    ) a order by lower(email), created_at desc
  ) x
 where v.name is null and v.email is not null and lower(v.email) = x.em;

-- ═══ 20261106120000_welcome_email.sql ════════════════════════════════════════════════
-- Welcome email through Resend when a new account's email is confirmed.
-- Fires on insert when confirmation is off or for Google sign-in, and on update when confirmation is on.
-- Accounts that are already confirmed never fire, so existing users get nothing.
alter table public.profiles add column if not exists welcome_sent_at timestamptz;

create or replace function private.send_welcome_email()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if new.email_confirmed_at is null or (tg_op = 'UPDATE' and old.email_confirmed_at is not null) then
    return new;
  end if;
  -- An email problem must never block a sign-up.
  begin
    perform net.http_post(
      url := 'https://gwdrtfcqqnvhwolbjkab.supabase.co/functions/v1/welcome-email',
      body := jsonb_build_object('user_id', new.id,
        'secret', (select decrypted_secret from vault.decrypted_secrets where name = 'registration_email_webhook')),
      headers := jsonb_build_object('Content-Type', 'application/json'),
      timeout_milliseconds := 10000
    );
  exception when others then
    raise warning 'welcome email not queued: %', sqlerrm;
  end;
  return new;
end;
$$;
revoke execute on function private.send_welcome_email() from public, anon, authenticated;

create trigger on_auth_user_welcome_email after insert or update of email_confirmed_at on auth.users
  for each row execute function private.send_welcome_email();

-- ═══ 20261108120000_uuid_role_authorization.sql ══════════════════════════════════════
-- Correct the email-based privilege bypass without rewriting applied history.
-- Existing owners remain attached to their profile UUID. No email grants ongoing privileges.
create or replace function private.is_admin()
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.profiles
    where id = (select auth.uid()) and role in ('owner', 'admin'));
$$;
revoke execute on function private.is_admin() from public;
grant execute on function private.is_admin() to anon, authenticated;

-- A team invite used to grant its role the moment someone signed up with that address,
-- before they proved they own it. The role now waits for a confirmed email.
-- This only protects invites while "Confirm email" is on in Supabase Auth.

create or replace function public.handle_new_user()
returns trigger language plpgsql security definer set search_path = '' as $$
declare invited public.app_role;
begin
  if new.email_confirmed_at is not null then
    select role into invited from public.team_invites
    where lower(email) = lower(new.email) and accepted_at is null;
  end if;
  if invited is not null then
    update public.team_invites set accepted_at = now()
      where lower(email) = lower(new.email) and accepted_at is null;
  end if;
  insert into public.profiles (id, email, full_name, role)
  values (new.id, new.email, coalesce(new.raw_user_meta_data ->> 'full_name', new.raw_user_meta_data ->> 'name'), coalesce(invited, 'member'));
  return new;
end;
$$;

create or replace function public.handle_user_confirmed()
returns trigger language plpgsql security definer set search_path = '' as $$
declare invited public.app_role;
begin
  if old.email_confirmed_at is null and new.email_confirmed_at is not null then
    update public.waitlist_entries set status = 'active' where lower(email) = lower(new.email);
    select role into invited from public.team_invites
    where lower(email) = lower(new.email) and accepted_at is null;
    if invited is not null then
      update public.profiles set role = invited where id = new.id;
      update public.team_invites set accepted_at = now() where lower(email) = lower(new.email) and accepted_at is null;
    end if;
  end if;
  return new;
end;
$$;

-- ═══ 20261109090000_admin_email_campaigns.sql ════════════════════════════════════════
-- Durable send claims prevent duplicate admin submissions across API instances.
create table public.admin_email_campaigns (
  id uuid primary key,
  created_by uuid not null references auth.users(id),
  subject text not null,
  content_hash text not null,
  recipients jsonb not null,
  recipient_count integer not null check (recipient_count between 1 and 1000),
  accepted_count integer not null default 0 check (accepted_count >= 0 and accepted_count <= recipient_count),
  status text not null check (status in ('sending', 'completed', 'failed')),
  error_code text,
  created_at timestamptz not null default now()
);
alter table public.admin_email_campaigns enable row level security;
revoke all on public.admin_email_campaigns from public, anon, authenticated;
grant select, insert, update on public.admin_email_campaigns to service_role;
-- No browser writes or public policies: the role-checked API owns this audit table.

